(4157805, 'Blackhowl Footsoldier', '', 135, 136, 0, 16, 0, 1, 1.14286, 20, 1, 1.0, 2000, 2000, 1, 2048, 7, 0, 0, '', 0, 1, 3.25, 1.0, 1, 1, 15595),
(4157806, 'Blackhowl Packmaster', '', 136, 136, 0, 16, 0, 1, 1.14286, 20, 1, 1.0, 2000, 2000, 1, 2048, 7, 0, 0, '', 0, 1, 4.25, 1.0, 1, 1, 15595),
